INSERT INTO `galaxy_proxy` VALUES (228, 'entityFilterCount', '/entity/filter/count', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count, <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> COUNT(DISTINCT(app_category)) AS category_distinct_count, COUNT(DISTINCT(app_subcategory)) AS subcategory_distinct_count, COUNT(DISTINCT(app_risk)) AS risk_distinct_count FROM entity_info WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> limit 1 <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> COUNT(DISTINCT(domain_category_group)) AS category_group_distinct_count, COUNT(DISTINCT(domain_category)) AS category_distinct_count, COUNT(DISTINCT(domain_reputation_level)) AS reputation_level_distinct_count FROM entity_info WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> limit 1 <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> COUNT(DISTINCT(ip_location_country)) AS country_distinct_count, COUNT(DISTINCT(ip_location_province)) AS province_distinct_count, COUNT(DISTINCT(ip_location_city)) AS city_distinct_count, COUNT(DISTINCT(ip_asn)) AS asn_distinct_count FROM entity_info WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> limit 1 <#else> ${parameter.dnsServerRoleCount} AS dns_server_role_count, ${parameter.dnsServerOrgCount} AS dns_server_org_count, ${parameter.dnsServerOsCount} AS dns_server_os_count, ${parameter.dnsServerSoftwareCount} AS dns_server_software_count, ${parameter.orgTotalCount} AS org_total_count, ${parameter.osTotalCount} AS os_total_count, ${parameter.softwareTotalCount} AS software_total_count FROM entity_info WHERE entity_type = \'ip\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} AND dns_server_role IS NOT NULL AND dns_server_role != \'\' <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> limit 1 </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nfunction isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;function isEmpty(a){\r\n if (a === \"\") return true;  if (a === null) return true; if (a === undefined) return true; if (!a && a !== 0 && a !==\"\") return true;  return false;\r\n }\r\nif(!isEmpty(parameter.entityType) && parameter.entityType==\"dns\"){\r\n var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\'); var param = [\"FWDNS\",\"ADNS\",\"OPRDNS\",\"TLDNS\",\"RTDNS\"]; var roleCount = 0; for(var key in param){ parameter.column = param[key]; var role = galaxyUtils.sendGalaxyRequest(\'/entity/filter/count/dns/role\',\'GET\',parameter);     if(role.success){\r\n var data =  role.data;       if(data.length > 0 && !isEmpty(data[0][\"count\"]) && data[0][\"count\"]>0){roleCount++; }    \r\n}}\r\nparameter.dnsServerRoleCount=roleCount; parameter.column =\"dns_server_os\"; var os = galaxyUtils.sendGalaxyRequest(\'/entity/filter/count/dns/others\',\'GET\',parameter);     if(os.success){\r\n var data =  os.data;       if(data.length > 0 && !isEmpty(data[0][\"os_count\"])){parameter.dnsServerOsCount = data[0][\"os_count\"]}else{parameter.dnsServerOsCount = 0; }   if(data.length > 0 && !isEmpty(data[0][\"os_total_count\"])){parameter.osTotalCount = data[0][\"os_total_count\"]}else{parameter.osTotalCount = 0; } \r\n}\r\nparameter.column =\"dns_server_software\"; var software = galaxyUtils.sendGalaxyRequest(\'/entity/filter/count/dns/others\',\'GET\',parameter);     if(software.success){\r\n var data =  software.data;       if(data.length > 0 && !isEmpty(data[0][\"software_count\"])){parameter.dnsServerSoftwareCount = data[0][\"software_count\"]}else{parameter.dnsServerSoftwareCount = 0; }  if(data.length > 0 && !isEmpty(data[0][\"software_total_count\"])){parameter.softwareTotalCount = data[0][\"software_total_count\"]}else{parameter.softwareTotalCount = 0; }   \r\n}\r\nparameter.column =\"dns_server_org\"; var org = galaxyUtils.sendGalaxyRequest(\'/entity/filter/count/dns/others\',\'GET\',parameter);     if(org.success){\r\n var data =  org.data;       if(data.length > 0 && !isEmpty(data[0][\"org_count\"])){parameter.dnsServerOrgCount = data[0][\"org_count\"]}else{parameter.dnsServerOrgCount = 0; }  if(data.length > 0 && !isEmpty(data[0][\"org_total_count\"])){parameter.orgTotalCount = data[0][\"org_total_count\"]}else{parameter.orgTotalCount = 0; }  \r\n}\r\n}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-15 09:03:12', '2021-12-15 09:03:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (229, 'entityFilterTop', '/entity/filter/top', 'v1', 'GET', '/', '{\r\n    \"query\": \"<#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"dns\"> <#if parameter.column?default(\'\')?trim? length gt 0&&parameter.column==\"dns_server_role\"> SELECT 0 AS count, dns_server_org AS name FROM entity_info WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime}<#else> SELECT COUNT(*) AS count, ${parameter.column} AS name FROM entity_info WHERE entity_type = \'ip\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} AND ${parameter.column} IS NOT NULL AND ${parameter.column} != \'\' <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> GROUP BY name ORDER BY count DESC LIMIT <#if parameter.top?default(\'\')?trim? length gt 0> ${parameter.top} <#else> 10 </#if> </#if> <#else> SELECT COUNT(*) AS count, ${parameter.column} AS name FROM entity_info WHERE entity_type=\'${parameter.entityType}\' AND update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.column?default(\'\')?trim? length gt 0&&parameter.column==\"app_risk\"> AND app_risk between 1 and 5 </#if> <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> GROUP BY name ORDER BY count DESC LIMIT <#if parameter.top?default(\'\')?trim? length gt 0> ${parameter.top} <#else> 10 </#if></#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nfunction isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	 var o={};\r\n 	o.resultType=\"table\";\r\n 	if(parameter.column==\"dns_server_role\"){\r\n var list = new java.util.ArrayList(); var param = [\"FWDNS\",\"ADNS\",\"OPRDNS\",\"TLDNS\",\"RTDNS\"];\r\n var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\nfor(var key in param){\r\n parameter.column=param[key]; var role = galaxyUtils.sendGalaxyRequest(\'/entity/filter/count/dns/role\',\'GET\',parameter);\r\n     if(role.success){\r\n var data =  role.data;\r\n       if(data.length > 0 &&!isEmpty(data[0][\"count\"])){\r\n var obj = {};\r\n obj.name=param[key];\r\n obj.count=data[0][\"count\"];\r\n list.add(obj);\r\n }\r\n    \r\n}\r\n}\r\n list.sort(function sortByCount(a,b){  \r\n				   return b.count-a.count;\r\n			}); o.result=list;}else{\r\n o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n  var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n }	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	 result.message=null;\r\n }', '2021-12-15 09:04:12', '2021-12-15 09:04:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (230, 'entityListBasic', '/entity/list/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\">entity_type AS entity_type, app_name AS app_name, app_id AS app_id, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk, app_description AS app_description <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\">entity_type AS entity_type, domain_name AS domain_name, domain_category AS domain_category, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_reputation_level AS domain_reputation_level <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\">entity_type AS entity_type, ip_addr AS ip_addr, ip_location_country AS ip_location_country, ip_location_province AS ip_location_province, ip_location_city AS ip_location_city, ip_asn AS ip_asn <#else>entity_type AS entity_type, ip_addr AS ip_addr, ip_location_country AS ip_location_country, ip_location_province AS ip_location_province, ip_location_city AS ip_location_city, ip_asn AS ip_asn, app_name AS app_name, app_id AS app_id, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk, app_description AS app_description, domain_name AS domain_name, domain_category AS domain_category, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_reputation_level AS domain_reputation_level </#if> FROM entity_info WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} <#if parameter.entityType?default(\'\')?trim? length gt 0> AND entity_type=\'${parameter.entityType}\' </#if>  <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> <#if parameter.where?default(\'\')?trim? length gt 0> ${parameter.where} </#if> ORDER BY update_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0&&parameter.pageNo?default(\'\')?trim? length gt 0> LIMIT ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'parameter.pageNo=(parameter.pageNo-1)*parameter.pageSize;\r\nif(parameter.where){\r\n	var data = JSON.parse(parameter.where);\r\n  	var str =\'\';\r\n  	for( key in data){\r\n      	str += \"and \"+key+\"=\"+\"\'\"+data[key]+\"\'\"\r\n    }\r\n        str = str.replace(/Unknown/ig,\"\")\r\n  	parameter.where =str;\r\n}\r\nfunction isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:05:12', '2021-12-15 09:05:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (231, 'entityListTraffic', '/entity/list/traffic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(SUM(common_c2s_byte_num)/ (${parameter.step})) AS bytes_sent_rate, ROUND(SUM(common_s2c_byte_num)/ (${parameter.step})) AS bytes_received_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} <#if parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"ip\"> AND (common_client_ip=\'${parameter.name}\' OR common_server_ip=\'${parameter.name}\') <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"domain\"> AND domain=\'${parameter.name}\' <#elseif parameter.entityType?default(\'\')?trim? length gt 0&&parameter.entityType==\"app\"> AND common_app_label=\'${parameter.name}\' </#if> GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + \"\";\r\n			aggregation.last = list[list.length - 1][key] + \"\";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = Math.round(sumValue / list.length) + \"\";\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key] + \"\";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-15 09:06:12', '2021-12-15 09:06:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (232, 'entityListAlertNum', '/entity/list/alertNum', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count FROM cn_alert WHERE entity_type = \'${parameter.entityType}\' AND entity_name = \'${parameter.name}\' AND start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:07:12', '2021-12-15 09:07:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (233, 'entityListDetectionNum', '/entity/list/detectionNum', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS count FROM cn_security_event WHERE destination_type = \'${parameter.entityType}\' AND destination_name = \'${parameter.name}\' AND start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-15 09:08:12', '2021-12-15 09:08:16', 1, '');
INSERT INTO `galaxy_proxy` VALUES (234, 'trafficTopAppCategories', '/traffic/topAppCategories', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT app_category AS app_category, uniq(common_app_label) AS uniq_apps, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) AND notEmpty(app_category) GROUP BY app_category ORDER BY uniq_apps desc LIMIT ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-16 13:46:32', '2021-12-16 13:46:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (235, 'trafficTopAppCategoriesList', '/traffic/appCategoriesList', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_app_label AS app_name, anyLast(app_category) AS app_category_name, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets, SUM(common_sessions) AS sessions FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(common_app_label) AND notEmpty(app_category) <#if parameter.appCategory?default(\'\')?trim? length gt 0> AND app_category in (<#list parameter.appCategory?split(\",\") as name><#if !name_has_next>\'${name}\'<#else>\'${name}\',</#if></#list>) </#if> GROUP BY common_app_label ORDER BY <#if parameter.order?default(\'\')?trim? length gt 0> ${parameter.order} desc <#else> sessions desc </#if> LIMIT ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-16 13:47:32', '2022-02-09 10:05:52', 1, '');
