b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nfunction sortByAvg(a,b){  \r\n       return b.aggregation.avg - a.aggregation.avg;\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields={};\r\n		var field = \"commonClientIp\";\r\n		var valueName=\"sslConLatency\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName]+\"\";\r\n			aggregation.last = list[list.length - 1][valueName]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	o.result.sort(sortByAvg);\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (294, 'entityDetailDomainClientIpPacketLoss', '/entity/detail/domain/clientIpPacketLoss', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time,     common_client_ip AS common_client_ip,     ROUND(AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)),4) AS sequence_gap_loss_percent FROM     session_record_cn WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_client_ip in (         SELECT             common_client_ip         FROM             session_record_cn         WHERE             common_recv_time > ${parameter.startTime}             AND common_recv_time < ${parameter.endTime}             AND domain = \'${parameter.domain}\'             AND notEmpty(common_client_ip)         GROUP BY             common_client_ip         ORDER BY             AVG((common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)) DESC         LIMIT 10         ) GROUP BY     stat_time,     common_client_ip\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields={};\r\n		var field = \"commonClientIp\";\r\n		var valueName=\"sequenceGapLossPercent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName]+\"\";\r\n			aggregation.last = list[list.length - 1][valueName]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2022-04-18 11:41:06', 1, '');
INSERT INTO `galaxy_proxy` VALUES (295, 'entityDetailDomainClientIpPacketRetrans', '/entity/detail/domain/clientIpPacketRetrans', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time,     common_client_ip AS common_client_ip,     ROUND(AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)),4) AS pkt_retrans_percent FROM     session_record_cn WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_client_ip in (         SELECT             common_client_ip         FROM             session_record_cn         WHERE             common_recv_time > ${parameter.startTime}             AND common_recv_time < ${parameter.endTime}             AND domain = \'${parameter.domain}\'            AND notEmpty(common_client_ip)         GROUP BY             common_client_ip         ORDER BY             AVG((common_c2s_pkt_retrans + common_s2c_pkt_retrans)/(common_c2s_pkt_num + common_s2c_pkt_num)) DESC         LIMIT 10         ) GROUP BY     stat_time,     common_client_ip\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields={};\r\n		var field = \"commonClientIp\";\r\n		var valueName=\"pktRetransPercent\";\r\n		for(var i=0;i<list.length;i++){\r\n			var value = fields[list[i][field]];\r\n			var values;\r\n			if(value){\r\n				values = fields[list[i][field]];\r\n				values.push(list[i]);\r\n			}else{\r\n				values = new Array();\r\n				values.push(list[i]);\r\n				fields[list[i][field]]=values;\r\n			}\r\n		}\r\n\r\n		for(var key in fields){\r\n			var list = fields[key];\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][valueName]+\"\";\r\n			aggregation.last = list[list.length - 1][valueName]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[valueName]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[valueName]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2022-04-18 11:41:33', 1, '');
INSERT INTO `galaxy_proxy` VALUES (296, 'entityDetailDomainLinkVisual', '/entity/detail/domain/linkVisual', 'v1', 'GET', '/', '{\r\n    \"query\": \"(SELECT common_ingress_link_id AS linkID,\'in\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND domain = \'${parameter.domain}\' GROUP BY linkID ORDER BY bytes DESC) UNION ALL (SELECT common_egress_link_id AS linkID,\'out\' as direction,SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,ROUND(AVG(common_establish_latency_ms)) AS latency,ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen)/ SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS lossPercent,ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num), 4) AS retransPercent FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_ingress_link_id != 0 AND common_egress_link_id !=0 AND domain = \'${parameter.domain}\' GROUP BY linkID ORDER BY bytes DESC)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (297, 'entityDetailOverviewIpDnsInfo', '/entity/detail/overview/ip/dnsInfo', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_server_role AS dns_server_role, dns_server_org AS dns_server_org, dns_server_software AS dns_server_software, dns_server_os AS dns_server_os, doh_support AS doh_support, dot_support AS dot_support, dnssec_support AS dnssec_support FROM entity_info WHERE dns_server_role != \'\' AND dns_server_role IS NOT NULL <#if parameter.ip?default(\'\')?trim? length gt 0> AND ip_addr = \'${parameter.ip}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-31 13:43:32', '2022-03-31 13:43:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (298, 'entityDetailAppCount', '/entity/detail/app/count', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT   count(distinct(common_client_ip)) AS client_ip_count FROM     session_record_cn WHERE     common_recv_time > ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} 	AND     common_app_label     = \'${parameter.appName}\' \",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\nparameter.start = parameter.startTime;\r\nparameter.end = parameter.endTime;\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (299, 'entityDetailAppSessions', '/entity/detail/app/sessions', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT         TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time,         ROUND(SUM(common_sessions)/${parameter.step}) AS session_rate FROM         session_record_cn WHERE         common_recv_time >= ${parameter.startTime} AND     common_recv_time  < ${parameter.endTime} AND     common_app_label     = \'${parameter.appName}\' GROUP BY         stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (300, 'entityDetailAppPackets', '/entity/detail/app/packets', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time,     ROUND(SUM(common_s2c_pkt_num)/${parameter.step}) AS bytes_received_rate,     ROUND(SUM(common_c2s_pkt_num)/${parameter.step}) AS bytes_sent_rate,     ROUND(SUM(common_c2s_pkt_num + common_s2c_pkt_num)/${parameter.step}) AS bytes_rate FROM    session_record_cn WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_app_label = \'${parameter.appName}\' GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n            if(key === \"packetsReceivedRate\" ){\r\n                lineObj.legend = \"received rate\";\r\n            }else if(key === \"packetsRentRate\" ){\r\n                lineObj.legend = \"sent rate\";\r\n            }else if(key === \"packetsRate\" ){\r\n                lineObj.legend = \"rate\";\r\n            }else{\r\n                lineObj.legend = key;\r\n            }\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (301, 'entityDetailAppBytes', '/entity/detail/app/bytes', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time,     ROUND(SUM(common_c2s_byte_num)/${parameter.step}) AS bytes_sent_rate,     ROUND(SUM(common_s2c_byte_num)/${parameter.step}) AS bytes_received_rate,     ROUND(SUM(common_c2s_byte_num + common_s2c_byte_num)/${parameter.step}) AS bytes_rate FROM     session_record_cn WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_app_label = \'${parameter.appName}\' GROUP BY     stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			\r\n			var lineObj = {};\r\n            if(key === \"bytesReceivedRate\" ){\r\n                lineObj.legend = \"received rate\";\r\n            }else if(key === \"bytesSentRate\" ){\r\n                lineObj.legend = \"sent rate\";\r\n            }else if(key === \"bytesRate\" ){\r\n                lineObj.legend = \"rate\";\r\n            }else{\r\n                lineObj.legend = key;\r\n            }\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (302, 'entityDetailAppTrafficMap', '/entity/detail/app/trafficMap', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     server_country AS server_country,  <#if parameter.country?default(\'\')?trim? length gt 0> server_province AS server_province, <#if parameter.province?default(\'\')?trim? length gt 0> server_region AS server_region, </#if> </#if>     SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_c2s_byte_num) AS sent_bytes, SUM(common_s2c_byte_num) AS received_bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets ,    SUM(common_sessions) as sessions FROM     session_record_cn WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime} 	AND  common_app_label   = \'${parameter.appName}\'  	<#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.province?default(\'\')?trim? length gt 0>AND server_country = \'${parameter.country}\'  AND server_province = \'${parameter.province}\' AND server_region != \'\' <#else> AND server_country = \'${parameter.country}\' AND server_province != \'\' </#if> <#else> AND server_country != \'\' </#if> GROUP BY server_country <#if parameter.country?default(\'\')?trim? length gt 0>,server_province <#if parameter.province?default(\'\')?trim? length gt 0>,server_region</#if></#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			\r\n			tempObj.serverId = countryCodeMap[tempObj.serverCountry];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.serverProvince){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.serverProvince];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (303, 'entityDetailAppActiveServerIP', '/entity/detail/app/activeServerIP', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     common_server_ip AS server_ip,     SUM(common_sessions) AS sessions,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets,     SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM     session_record_cn WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND common_app_label = \'${parameter.appName}\' GROUP BY     server_ip ORDER BY      ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (304, 'entityDetailAppTopDomains', '/entity/detail/app/topDomains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT     domain AS domain,     SUM(common_sessions) AS sessions,     SUM(common_c2s_pkt_num + common_s2c_pkt_num) as packets,     SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM     session_record_cn WHERE     common_recv_time >= ${parameter.startTime}     AND common_recv_time < ${parameter.endTime}     AND notEmpty(domain)     AND common_app_label = \'${parameter.appName}\' GROUP BY     domain ORDER BY     ${parameter.order} desc limit ${parameter.limit}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}\r\n', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\n			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (305, 'entityDetailAppServiceOverview', '/entity/detail/app/serviceOverview', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT   ${parameter.httpResponseLatencyMs} AS http_response_latency_ms, ${parameter.sslConLatencyMs} AS ssl_con_latency_ms, ${parameter.establishLatencyMs} AS establish_latency_ms, ${parameter.sequenceGapLossPercent} AS sequence_gap_loss_percent, ${parameter.pktRetransPercent} AS pkt_retrans_percent FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';function isEmpty(a){\r\n if (a === \"\") return true;  if (a === null) return true; if (a === undefined) return true; if (!a && a !== 0 && a !==\"\") return true;  return false;\r\n }\r\n      var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');     var http = galaxyUtils.sendGalaxyRequest(\'/entity/detail/app/serviceOverview/2\',\'GET\',parameter);     if(http.success){\r\n var data =  http.data;       if(!isEmpty(data[0][\"http_response_latency_ms\"])){parameter.httpResponseLatencyMs = data[0][\"http_response_latency_ms\"].toString(); }else{parameter.httpResponseLatencyMs = \'null\';}    \r\n} \r\n\r\nvar ssl = galaxyUtils.sendGalaxyRequest(\'/entity/detail/app/serviceOverview/3\',\'GET\',parameter);\r\n     if(ssl.success){\r\n var data =  ssl.data;\r\n if(!isEmpty(data[0][\"ssl_con_latency_ms\"])){\r\nparameter.sslConLatencyMs = data[0][\"ssl_con_latency_ms\"].toString();\r\n}else{parameter.sslConLatencyMs = \'null\';}\r\n     }\r\n var result = galaxyUtils.sendGalaxyRequest(\'/entity/detail/app/serviceOverview/145\',\'GET\',parameter);\r\n     if(result.success){\r\n var data = result.data;\r\n if(!isEmpty(data[0][\"establish_latency_ms\"])){parameter.establishLatencyMs = data[0][\"establish_latency_ms\"].toString()}else{parameter.establishLatencyMs = \'null\';};\r\n if(!isEmpty(data[0][\"sequence_gap_loss_percent\"])){parameter.sequenceGapLossPercent = data[0][\"sequence_gap_loss_percent\"].toString()}else{parameter.sequenceGapLossPercent = \'null\';};\r\n if(!isEmpty(data[0][\"pkt_retrans_percent\"])){parameter.pktRetransPercent = data[0][\"pkt_retrans_percent\"].toString()}else{parameter.pktRetransPercent = \'null\'};\r\n   }\r\n \r\n\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (306, 'entityDetailAppOverallEstablishlatency', '/entity/detail/app/overallEstablishlatency', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') as stat_time, ROUND(AVG(common_establish_latency_ms)) AS establish_latency FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\',\'IPv6_TCP\') AND common_app_label = \'${parameter.appName}\' GROUP BY stat_time\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key]+\"\";\r\n			aggregation.last = list[list.length - 1][key]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			\r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-30 13:03:32', '2021-12-30 13:03:36', 1, '');
