){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n	for(var i in list){\r\n             var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i in fields) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + \"\";\r\n			aggregation.last = list[list.length - 1][key] + \"\";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = Math.round(sumValue / list.length) + \"\";\r\n			 \r\n			var plist = new Array();\r\n            for(var i=0; i<values.length; i++){\r\n                plist.push(values[i][1]);\r\n            }\r\n            aggregation.p50 = getPercentile(plist, 0.5);\r\n            aggregation.p90 = getPercentile(plist, 0.9);\r\n            aggregation.max = plist[plist.length-1]+\"\";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2021-12-31 13:03:32', '2022-03-25 10:03:15', 1, '');
