INSERT INTO `galaxy_proxy` VALUES (391, 'detectionPerformanceListBasic', '/detection/performance/list/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT entity_type AS entity_type, server_ip AS server_ip, domain AS domain, app_name AS app_name, event_severity AS event_severity, event_type AS event_type, start_time AS start_time, duration_ms AS duration_ms, end_time AS end_time FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> ORDER BY start_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0&&parameter.pageNo?default(\'\')?trim? length gt 0> LIMIT ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\nparameter.pageNo=(parameter.pageNo-1)*parameter.pageSize;', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-02-25 13:03:32', '2022-02-25 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (392, 'detectionPerformanceDetailOverviewBasic', '/detection/performance/detail/overview/basic', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT server_location_country AS server_location_country, server_location_province AS server_location_province, server_location_region AS server_location_region, server_asn AS server_asn, domain_category_name AS domain_category_name, domain_category_group AS domain_category_group, domain_reputation_score AS domain_reputation_score, domain_reputation_level AS domain_reputation_level, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.serverIp?default(\'\')?trim? length gt 0> AND server_ip = \'${parameter.serverIp}\' </#if><#if parameter.appName?default(\'\')?trim? length gt 0> AND app_name = \'${parameter.appName}\' </#if><#if parameter.domain?default(\'\')?trim? length gt 0> AND domain = \'${parameter.domain}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\n;', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-02-25 13:03:32', '2022-02-25 13:03:36', 1, '');
