INSERT INTO `galaxy_proxy` VALUES (398, 'dnsOs', '/dns/os', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_server_os AS name, COUNT(DISTINCT(ip_addr)) AS num FROM entity_info WHERE dns_server_role !=\'\' AND dns_server_role IS NOT NULL AND dns_server_os != \'\' AND dns_server_os IS NOT NULL GROUP BY dns_server_os\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (399, 'dnsSoftware', '/dns/software', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_server_software AS name, COUNT(DISTINCT(ip_addr)) AS num FROM entity_info WHERE dns_server_role !=\'\' AND dns_server_role IS NOT NULL AND dns_server_software != \'\' AND dns_server_software IS NOT NULL GROUP BY dns_server_software\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (400, 'dnsOrg', '/dns/org', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_server_org AS name, COUNT(DISTINCT(ip_addr)) AS num FROM entity_info WHERE dns_server_role !=\'\' AND dns_server_role IS NOT NULL AND dns_server_org != \'\' AND dns_server_org IS NOT NULL GROUP BY dns_server_org\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (401, 'dnsDnssecSupport', '/dns/dnssecSupport', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count <#if parameter.sum?default(\'\')?trim? length gt 0> , ROUND(CAST(COUNT(DISTINCT(ip_addr)) AS DOUBLE)/${parameter.sum},4)<#else>, 0 </#if> AS percent FROM entity_info WHERE dnssec_support = \'true\' AND dns_server_role != \'\' AND dns_server_role IS NOT NULL LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/dnsCount\',\'GET\',parameter);\r\n if(result.success&&result.data!=0){\r\nparameter.sum = Number(result.data[0][\'count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (402, 'dnsIpv6Support', '/dns/ipv6Support', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count <#if parameter.sum?default(\'\')?trim? length gt 0> , ROUND(CAST(COUNT(DISTINCT(ip_addr)) AS DOUBLE)/${parameter.sum},4) <#else>, 0 </#if> AS percent FROM entity_info WHERE ip_addr LIKE \'%:%\' AND dns_server_role != \'\' AND dns_server_role IS NOT NULL LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/dnsCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n	}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (403, 'dnsEncryptedProtocolSupport', '/dns/encryptedProtocolSupport', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT \'${parameter.doh}\' AS doh ,\'${parameter.dot}\' AS dot FROM entity_info LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/dnsCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'count\']);\r\n}\r\nvar galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var hresult = galaxyUtils.sendGalaxyRequest(\'/dns/dohCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.doh = hresult.data[0].toString();\r\n}else{\r\nparameter.doh = \"{}\"\r\n}\r\n var tresult = galaxyUtils.sendGalaxyRequest(\'/dns/dotCount\',\'GET\',parameter);\r\n if(tresult.success){\r\nparameter.dot = tresult.data[0].toString();\r\n}else{\r\nparameter.dot = \"{}\"\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		var str = pojo[key].replace(/=/g,\":\");\r\n var json = eval(\"(\" + str + \")\");\r\n	tempObj[tempKey] = json	}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (404, 'dnsDohCount', '/dns/dohCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count<#if parameter.sum?default(\'\')?trim? length gt 0>, ROUND(CAST(COUNT(DISTINCT(ip_addr)) AS DOUBLE)/${parameter.sum},4) <#else>, 0 </#if> AS percent FROM entity_info WHERE doh_support = \'true\' AND dns_server_role != \'\' AND dns_server_role IS NOT NULL LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/dnsCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (405, 'dnsDotCount', '/dns/dotCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count <#if parameter.sum?default(\'\')?trim? length gt 0> , ROUND(CAST(COUNT(DISTINCT(ip_addr)) AS DOUBLE)/${parameter.sum},4)<#else>, 0 </#if> AS percent FROM entity_info WHERE dot_support = \'true\' AND dns_server_role != \'\' AND dns_server_role IS NOT NULL LIMIT 1\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/dnsCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (406, 'dnsMap', '/dns/map', 'v1', 'GET', '/', '{\r\n    \"query\": \"<#if parameter.dnsServerRole?default(\'\')?trim? length gt 0 && parameter.dnsServerRole?upper_case == \'RTDNSM\'>SELECT dns_root_mirror_locations FROM entity_info WHERE dns_server_role = \'RTDNS\' <#else>SELECT dns_server_role AS dns_server_role, ip_location_country AS ip_location_country, COUNT(DISTINCT(ip_addr)) AS count <#if parameter.ipLocationCountry?default(\'\')?trim? length gt 0>, ip_location_province AS ip_location_province <#if parameter.ipLocationProvince?default(\'\')?trim? length gt 0>, ip_location_city AS ip_location_city </#if> </#if> FROM entity_info WHERE dns_server_role = \'${parameter.dnsServerRole}\' <#if parameter.ipLocationCountry?default(\'\')?trim? length gt 0> <#if parameter.ipLocationProvince?default(\'\')?trim? length gt 0>AND ip_location_country = \'${parameter.ipLocationCountry}\' AND ip_location_province = \'${parameter.ipLocationProvince}\' AND ip_location_city != \'\' <#else> AND ip_location_country = \'${parameter.ipLocationCountry}\' AND ip_location_province != \'\' </#if> <#else> AND ip_location_country != \'\' </#if>  GROUP BY dns_server_role, ip_location_country <#if parameter.ipLocationCountry?default(\'\')?trim? length gt 0>,ip_location_province <#if parameter.ipLocationProvince?default(\'\')?trim? length gt 0>,ip_location_city</#if></#if></#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function (all, letter) {\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\nfunction isEmpty(a) {\r\n    if (a === \"\")\r\n        return true;\r\n    if (a === \"null\")\r\n        return true;\r\n    if (a === \"undefined\")\r\n        return true;\r\n    if (!a && a !== 0 && a !== \"\")\r\n        return true;\r\n    if (Array.prototype.isPrototypeOf(a) && a.length === 0)\r\n        return true;\r\n    if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0)\r\n        return true;\r\n    return false;\r\n}\r\n\r\nif (result.success) {\r\n    var o = {};\r\n    o.resultType = \"table\";\r\n    if (!isEmpty(parameter.dnsServerRole) && parameter.dnsServerRole.toUpperCase()===\"RTDNSM\") {\r\n        var tempObj = new java.util.ArrayList();\r\n        if (result.data.length > 0) {\r\n            for (var i in result.data) {\r\n                var pojo = result.data[i];\r\n                var obj;\r\n                for (var key in pojo) {\r\n                    obj = pojo[key];\r\n                }\r\n                var arr = eval(obj);\r\n                for (var i = 0; i < arr.length; i++) {\r\n                    var pojo = arr[i];\r\n                    tempObj.add(pojo);\r\n                }\r\n                o.result = tempObj;\r\n\r\n            }\r\n        }\r\n    } else {\r\n   o.result = result.data;     if (o.result.length > 0) {\r\n            for (var i in o.result) {\r\n                var pojo = o.result[i];\r\n                var tempObj = {};\r\n\r\n                for (var key in pojo) {\r\n                    var tempKey = toHump(key);\r\n                    tempObj[tempKey] = pojo[key];\r\n                }\r\n                for (var item in countryCodeMap) {\r\n                    if (item.toLowerCase() == tempObj.ipLocationCountry.toLowerCase()) {\r\n                        tempObj.ipLocationId = countryCodeMap[item];\r\n                    }\r\n                }\r\n                if (!tempObj.ipLocationId) {\r\n                    tempObj.ipLocationId = \"\";\r\n                } else {\r\n                    // 存在地区\r\n                    if (tempObj.ipLocationProvince) {\r\n                        for (var item in countCityMap[tempObj.ipLocationId]) {\r\n                            if (item.toLowerCase() == tempObj.ipLocationProvince.toLowerCase()) {\r\n                                var regionCode = countCityMap[tempObj.ipLocationId][item];\r\n                                if (regionCode) {\r\n                                    tempObj.ipLocationId = regionCode;\r\n                                }\r\n                            }\r\n                        }\r\n                    }\r\n                }\r\n                o.result[i] = tempObj;\r\n            }\r\n        }\r\n    }\r\n    result.code = 200;\r\n    result.data = o;\r\n    result.msg = result.message;\r\n    result.message = null;\r\n}\r\n', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (407, 'dnsQueryRate', '/dns/queryRate', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(COUNT(*)/${parameter.step},4) AS query_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY stat_time ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key] + \"\";\r\n			aggregation.last = list[list.length - 1][key] + \"\";\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = Math.round(sumValue / list.length) + \"\";\r\n			 \r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (408, 'dnsQueryCount', '/dns/queryCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT SUM(IF(dns_qr =0,1,0)) AS query_count FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(dns_protocol)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=Number(o.result[0][key])\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (409, 'dnsDohInquiries', '/dns/dohInquiries', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT SUM(IF(dns_qr =0,1,0)) AS count <#if parameter.sum?default(\'\')?trim? length gt 0> , ROUND(CAST(SUM(IF(dns_qr =0,1,0)) AS DOUBLE)/${parameter.sum},4) <#else>, 0 </#if> AS percent FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time <${parameter.endTime} AND dns_protocol = \'doh\' AND notEmpty(dns_server_role)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/queryCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'query_count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = Number(pojo[key]);\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (410, 'dnsDotInquiries', '/dns/dotInquiries', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT SUM(IF(dns_qr =0,1,0)) AS count <#if parameter.sum?default(\'\')?trim? length gt 0&&parameter.sum!=0> , ROUND(CAST(SUM(IF(dns_qr =0,1,0)) AS DOUBLE)/${parameter.sum},4) <#else>, 0 </#if> AS percent FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND dns_protocol = \'dot\' AND notEmpty(dns_server_role)\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\n var galaxyUtils = Java.type(\'net.geedge.common.utils.GalaxyUtils\');\r\n var result = galaxyUtils.sendGalaxyRequest(\'/dns/queryCount\',\'GET\',parameter);\r\n if(result.success){\r\nparameter.sum = Number(result.data[0][\'query_count\']);\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = Number(pojo[key]);\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (411, 'dnsActiveClientIp', '/dns/activeClientIp', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_client_ip AS server_ip, COUNT(*) AS query_count, ROUND(AVG(dns_response_latency_ms)) AS dns_latency, ROUND(SUM(IF(dns_rcode = 0,0,1))/COUNT(dns_rcode),4) AS response_fail_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY common_client_ip ORDER BY ${parameter.order} DESC <#if parameter.limit?default(\'\')?trim? length gt 0> Limit ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nfunction toLine(name) {   return name.replace(/([A-Z])/g,\"_$1\").toLowerCase(); }\r\nif(parameter.order){parameter.order = toLine(parameter.order);}', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (412, 'dnsActiveDomainServer', '/dns/activeDomainServer', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_server_ip AS server_ip, ROUND(SUM(IF(dns_qr =0,1,0))/toUnixTimestamp(${parameter.endTime} - ${parameter.startTime}),2) AS query_rate, ROUND(AVG(dns_response_latency_ms)) AS dns_latency, ROUND(COUNT(*)/COUNT(dns_rcode),4) AS response_fail_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY common_server_ip ORDER BY ${parameter.order} DESC <#if parameter.limit?default(\'\')?trim? length gt 0> Limit ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nfunction toLine(name) {   return name.replace(/([A-Z])/g,\"_$1\").toLowerCase(); }\r\nif(parameter.order){parameter.order = toLine(parameter.order);}', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (413, 'dnsResolveDomain', '/dns/resolveDomain', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_qname AS dns_qname, COUNT(*) AS query_count, ROUND(AVG(dns_response_latency_ms)) AS dns_latency, ROUND(SUM(IF(dns_rcode = 0,0,1))/COUNT(dns_rcode),4) AS response_fail_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(dns_qname) AND common_schema_type = \'DNS\' GROUP BY dns_qname ORDER BY ${parameter.order} DESC <#if parameter.limit?default(\'\')?trim? length gt 0> Limit ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\nfunction toLine(name) {   return name.replace(/([A-Z])/g,\"_$1\").toLowerCase(); }\r\nif(parameter.order){parameter.order = toLine(parameter.order);}', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (414, 'dnsAverageResolveLatency', '/dns/averageResolveLatency', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(AVG(dns_response_latency_ms)) AS dns_latency FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY stat_time ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key]+\"\";\r\n			aggregation.last = list[list.length - 1][key]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n	         	var lineObj = {};\r\n                        lineObj.legend = key;	\r\n			lineObj.values = values;	\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (415, 'dnsResponseFailureRate', '/dns/responseFailureRate', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(SUM(IF(dns_rcode = 1,1,0))/COUNT(dns_rcode),4) AS format_error_rate, ROUND(SUM(IF(dns_rcode = 2,1,0))/COUNT(dns_rcode),4) AS server_failure_rate, ROUND(SUM(IF(dns_rcode = 3,1,0))/COUNT(dns_rcode),4) AS non_existent_domain_rate, ROUND(SUM(IF(dns_rcode = 4,1,0))/COUNT(dns_rcode),4) AS not_implemented_rate, ROUND(SUM(IF(dns_rcode = 5,1,0))/COUNT(dns_rcode),4) AS query_refused_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY stat_time ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n return (a - b);\r\n }\r\nfunction getPercentile(list, p){\r\n var n = list.length;\r\n list.sort(f);\r\n var px =  p*(n-1);\r\n var i = Math.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i in fields) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key]+\"\";\r\n			aggregation.last = list[list.length - 1][key]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n	         	var lineObj = {};\r\n                        lineObj.legend = key;	\r\n			lineObj.values = values;	\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (416, 'dnsAlarmInfo', '/dns/alarmInfo', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT entity_type AS entity_type, server_ip AS server_ip, domain AS domain, app_name AS app_name, event_severity AS event_severity, event_type AS event_type, start_time AS start_time, duration_ms AS duration_ms, end_time AS end_time FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.eventSeverity?default(\'\')?trim? length gt 0> AND event_severity = \'${parameter.eventSeverity}\' </#if> ORDER BY start_time DESC <#if parameter.pageNo?default(\'\')?trim? length gt 0&&parameter.pageSize?default(\'\')?trim? length gt 0> limit ${parameter.pageNo}, ${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\nparameter.pageNo=(parameter.pageNo-1)*parameter.pageSize;', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (417, 'dnsAlarmInfoCount', '/dns/alarmInfoCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.eventSeverity?default(\'\')?trim? length gt 0> AND event_severity = \'${parameter.eventSeverity}\' </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (418, 'dnsCount', '/dns/dnsCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count FROM entity_info WHERE dns_server_role != \'\' AND dns_server_role IS NOT NULL\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (419, 'entityDetailIpPort', '/entity/detail/ip/port', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_server_port as server_port, common_l7_protocol AS protocol, http_response_line AS http_response_line, common_recv_time AS recv_time FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip=\'${parameter.ip}\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (420, 'detectionPerformanceDetailOverviewMetric', '/detection/performance/detail/overview/metric', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(UNIX_TIMESTAMP(common_recv_time),\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(SUM(IF(dns_rcode = 0,0,1))/COUNT(dns_rcode),4) AS dns_error_rate FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' <#if parameter.serverIp?default(\'\')?trim? length gt 0> AND common_server_ip = \'${parameter.serverIp}\' <#elseif parameter.appName?default(\'\')?trim? length gt 0> AND common_app_label = \'${parameter.appName}\' <#elseif parameter.domain?default(\'\')?trim? length gt 0> <#if parameter.eventType==\'dns error\' || parameter.eventType==\'high dns response time\'> AND dns_qname = \'${parameter.domain}\' <#elseif parameter.eventType==\'http error\'> AND domain = \'${parameter.domain}\' </#if> </#if> GROUP BY stat_time ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n                         var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n	\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			 \r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			aggregation.max = list[0][key];\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			 lineObj.legend = key;\r\n			lineObj.aggregation = aggregation;\r\n			 o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	 \r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (421, 'detectionPerformanceFilterActiveEntity', '/detection/performance/filter/activeEntity', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT entity_type AS entity_type, IIF(entity_type = \'domain\',domain, IIF(entity_type = \'ip\',server_ip, app_name)) AS name, COUNT(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if> GROUP BY entity_type, app_name, domain, server_ip ORDER by count DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-10-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (422, 'entityDetailIpDomains', '/entity/detail/ip/domains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_server_ip=\'${parameter.ip}\' AND notEmpty(domain) GROUP BY domain ORDER BY bytes DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-03 10:03:32', '2022-03-03 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (423, 'entityDetailIpDomainByCategory', '/entity/detail/ip/domainByCategory', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain_category_name AS category_name, uniq(domain) AS uniq_domains FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain_category_name) <#if parameter.domains?default(\'\')?trim? length gt 0> AND domain in (<#list parameter.domains?split(\",\") as domain><#if !domain_has_next>\'${domain}\'<#else>\'${domain}\',</#if></#list>) </#if> GROUP BY domain_category_name\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-21 10:03:32', '2022-03-21 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (424, 'entityDetailIpDomainByReputation', '/entity/detail/ip/domainByReputation', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain_reputation_level AS reputation_level, uniq(domain) AS uniq_domains FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(domain_reputation_level) <#if parameter.domains?default(\'\')?trim? length gt 0> AND domain in (<#list parameter.domains?split(\",\") as domain><#if !domain_has_next>\'${domain}\'<#else>\'${domain}\',</#if></#list>) </#if> GROUP BY domain_reputation_level\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-03-21 10:03:32', '2022-03-21 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (425, 'entityDetailAppDomains', '/entity/detail/app/domains', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT domain AS domain, SUM(common_c2s_byte_num + common_s2c_byte_num) as bytes FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_app_label = \'${parameter.appName}\' AND notEmpty(domain) GROUP BY domain ORDER BY bytes DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'if(result.success){\r\n    \r\n	var o={};\r\n	\r\n	var list = result.data;\r\n        var arr = new java.util.ArrayList();  \r\n        if(list.length > 0){\r\n            for(var i=0; i< list.length; i++){\r\n                var pojo = list[i];\r\n                arr.add(pojo[\"domain\"])  \r\n            }\r\n        }       \r\n	o.resultType=\"array\"\r\n	o.result=arr;\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-03-22 10:03:32', '2022-03-22 13:03:36', 1, '');
