ath.floor(px);\r\n var g = px - i;\r\n if(g==0){\r\n return list[i];\r\n }else{\r\n return (1-g)*list[i]+g*list[i+1];\r\n }\r\n }\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	if(list.length > 0){\r\nfor(var i in list){\r\n      var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			 }\r\n 			list[i] = tempObj;\r\n         }\r\n		\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key]+\"\";\r\n			aggregation.last = list[list.length - 1][key]+\"\";\r\n			\r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				tempArray.push(pojo[\"statTime\"]);\r\n				tempArray.push((pojo[key]).toString());\r\n				values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			}\r\n			aggregation.avg = (sumValue / list.length).toFixed(2);\r\n			\r\n			var plist = new Array();\r\n for(var i=0; i<values.length; i++){\r\n plist.push(values[i][1]);\r\n }\r\n aggregation.p50 = getPercentile(plist, 0.5);\r\naggregation.p90 = getPercentile(plist, 0.9);\r\naggregation.max = plist[plist.length-1]+\"\";\r\n	         	var lineObj = {};\r\n                        lineObj.legend = key;	\r\n			lineObj.values = values;	\r\n			lineObj.aggregation = aggregation;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n	\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-04-19 13:43:32', '2022-04-19 13:43:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (446, 'dnsRtMirrors', '/dns/rtMirrors', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_root_mirror_locations FROM entity_info WHERE dns_server_role = \'RTDNS\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function isEmpty(a){\r\n if (a === \"\") return true;\r\n if (a === \"null\") return true;\r\n if (a === \"undefined\") return true;\r\n if (!a && a !== 0 && a !==\"\") return true;\r\n         if (Array.prototype.isPrototypeOf(a) && a.length === 0 ) return true;\r\n if (Object.prototype.isPrototypeOf(a) && Object.keys(a).length === 0 ) return true;\r\n return false;\r\n }\r\nif (isEmpty(parameter.endTime)) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (isEmpty(parameter.startTime)) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-04-24 13:43:32', '2022-04-24 13:43:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (447, 'dnsRtMirrorsCount', '/dns/rtMirrorsCount', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT dns_root_mirror_locations FROM entity_info WHERE dns_server_role = \'RTDNS\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'if(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=\"\";\r\n	var arr = result.data;\r\n arr = eval(arr); var temparr = [];for(var i in arr){\r\n var pojo = arr[i]; for(var key in pojo){\r\n var str = pojo[key];\r\n str = eval(str);\r\n for(var i in str){\r\n temparr.push(str[i]);\r\n  };\r\n }\r\n  }\r\n o.result=temparr.length;\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-04-25 10:03:32', '2022-04-25 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (448, 'dnsFwdns', '/dns/fwdns', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(DISTINCT(ip_addr)) AS count FROM entity_info WHERE dns_server_role like \'%FWDNS%\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', '', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"single\"\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var key in o.result[0]){\r\n			o.result=o.result[0][key]\r\n		}\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-05-10 10:03:32', '2022-05-10 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (449, 'entityFilterCountDnsRole', '/entity/filter/count/dns/role', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT count(*) AS count <#if parameter.column?default(\'\')?trim? length gt 0>, \'${parameter.column}\' AS dns_server_role </#if> FROM entity_info WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} AND entity_type = \'ip\' <#if parameter.column?default(\'\')?trim? length gt 0> AND QUERY(\'dns_server_role:${parameter.column}\') <#else> AND dns_server_role IS NOT NULL AND dns_server_role != \'\' </#if> <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-05-11 10:03:32', '2022-05-11 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (450, 'entityFilterCountDnsOthers', '/entity/filter/count/dns/others', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT <#if parameter.column?default(\'\')?trim? length gt 0 && parameter.column?lower_case == \'dns_server_org\'> count(DISTINCT dns_server_org) AS org_count, count(*) AS org_total_count <#elseif parameter.column?default(\'\')?trim? length gt 0 && parameter.column?lower_case == \'dns_server_os\'> count(DISTINCT dns_server_os) AS os_count, count(*) AS os_total_count <#else> count(DISTINCT dns_server_software) AS software_count, count(*) AS software_total_count</#if> FROM entity_info WHERE update_time >= ${parameter.startTime} AND update_time < ${parameter.endTime} AND entity_type = \'ip\' <#if parameter.column?default(\'\')?trim? length gt 0 && parameter.column?lower_case == \'dns_server_org\'> AND dns_server_org IS NOT NULL AND dns_server_org != \'\' <#elseif parameter.column?default(\'\')?trim? length gt 0 && parameter.column?lower_case == \'dns_server_os\'> AND dns_server_os IS NOT NULL AND dns_server_os != \'\' <#else> AND dns_server_software IS NOT NULL AND dns_server_software != \'\' </#if> <#if parameter.q?default(\'\')?trim? length gt 0> AND ${parameter.q} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-05-11 10:03:32', '2022-05-11 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (484, 'overviewApplicationTrafficAnalysis', '/overview/applicationTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${parameter.step}S\',\'zero\') AS stat_time, common_app_label AS app_label, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(common_sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND common_app_label IN (<#list parameter.appLabels?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY stat_time,app_label ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new java.util.HashMap();\r\n		for(var i in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (var key in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appLabel\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByStatTime);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					if(pojo[\"appLabel\"]==m){\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key]]);\r\n					}\r\n				}\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = Number((sumValue/parameter.timeDiff).toFixed(2));\r\n				analysis.total = sumValue;\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[m] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (485, 'overviewApplicationCycleTrafficTotal', '/overview/applicationCycleTrafficTotal', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT common_app_label AS app_label, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(common_sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} AND common_app_label IN (<#list parameter.appLabels?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY app_label\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime;\r\n', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new java.util.HashMap();\r\n		for(var i in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (var key in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appLabel\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByStatTime);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					if(pojo[\"appLabel\"]==m){\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key]]);\r\n					}\r\n				}\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = Number((sumValue/parameter.timeDiff).toFixed(2));\r\n				analysis.total = sumValue;\r\n				\r\n				obj[m] = analysis;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\n\r\n', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (486, 'overviewAppCompanyTrafficAnalysis', '/overview/appCompanyTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${parameter.step}S\',\'zero\') AS stat_time, app_company AS app_company, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(common_sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND app_company IN (<#list parameter.appCompanies?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY stat_time,app_company ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new java.util.HashMap();\r\n		for(var i in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (var key in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appCompany\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByStatTime);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					if(pojo[\"appCompany\"]==m){\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key]]);\r\n					}\r\n				}\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = Number((sumValue/parameter.timeDiff).toFixed(2));\r\n				analysis.total = sumValue;\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[m] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (487, 'overviewAppCompanyCycleTrafficTotal', '/overview/appCompanyCycleTrafficTotal', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT app_company AS app_company, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(common_sessions) AS sessions_total FROM metric_application WHERE stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} AND app_company IN (<#list parameter.appCompanies?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY app_company\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';\r\n', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		var name = new java.util.HashMap();\r\n		for(var i in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (var key in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(tempKey == \'appCompany\'){\r\n					name.put(tempObj[tempKey],tempObj[tempKey]);\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n		}\r\n		\r\n		var type = {};\r\n		type.bytes = \'bytesTotal\';\r\n		type.packets = \'packetsTotal\';\r\n		type.sessions = \'sessionsTotal\';\r\n		for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in name){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByStatTime);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					if(pojo[\"appCompany\"]==m){\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"statTime\"]);\r\n					tempArray.add(pojo[type[key]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key]]);\r\n					}\r\n				}\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				analysis.rate = Number((sumValue/parameter.timeDiff).toFixed(2));\r\n				analysis.total = sumValue;\r\n				\r\n				obj[m] = analysis;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}\r\n\r\n\r\n', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (488, 'overviewEventSeverity', '/overview/eventSeverity', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT event_severity AS event_severity, COUNT(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY event_severity\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"object\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (489, 'overviewEventType', '/overview/eventType', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT event_type AS event_type, COUNT(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY event_type\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"object\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (490, 'overviewDdosEventAnalysis', '/overview/ddosEventAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT COUNT(*) AS attack_event_count, COUNT(DISTINCT(offender_ip)) AS attacker_count, COUNT(DISTINCT(victim_ip)) AS victim_count FROM security_event WHERE start_time >= ${parameter.startTime} AND start_time < ${parameter.endTime} AND security_type = \'ddos\'\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"object\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-07-27 10:03:32', '2022-07-27 13:03:36', 1, '');
INSERT INTO `galaxy_proxy` VALUES (491, 'overviewTotalTrafficAnalysis', '/overview/totalTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT granularity AS granularity,SUM(total_bytes) AS bytes_total,SUM(total_packets) AS packets_total,SUM(total_sessions) AS total_sessions,SUM(inbound_bytes) AS inbound_bytes,SUM(inbound_packets) AS inbound_packets,SUM(outbound_bytes) AS outbound_bytes,SUM(outbound_packets) AS outbound_packets,SUM(internal_bytes) AS internal_bytes,SUM(internal_packets) AS internal_packets,SUM(external_bytes) AS through_bytes,SUM(external_packets) AS through_packets FROM ( SELECT TIME_FLOOR_WITH_FILL(common_recv_time,\'PT${parameter.step}S\',\'zero\') AS granularity,SUM(common_s2c_byte_num + common_c2s_byte_num) AS total_bytes,SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS total_packets,SUM(common_sessions) AS total_sessions,IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_byte_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes,IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_pkt_num), 0)) AS inbound_packets,IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes,IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets,IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes,IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets,IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS external_bytes,IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS external_packets FROM session_record_cn AS a WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY granularity,client_zone,server_zone ORDER BY granularity )GROUP BY granularity ORDER BY granularity ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nparameter.step = parameter.step>=30?parameter.step:30;', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByGranularity(a,b){  \r\n       return a.granularity - b.granularity;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		for(var i in list){\r\n			var temp = list[i];\r\n			var tempObj= {};\r\n			for (var key in temp){\r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = temp[key];\r\n				if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (temp[key] / parameter.step).toFixed(2)\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n			list[i].granularity = list[i].granularity;\r\n		}\r\n		var bytes = [];\r\n		var packets = [];\r\n		var sessions = [];\r\n		for(var key in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Packets\") != -1){\r\n				packets.push(key);\r\n			} else if(key.indexOf(\"Sessions\") != -1){\r\n				sessions.push(key);\r\n			}\r\n		}\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.packets = packets;\r\n		type.sessions = sessions;\r\n		for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in type[key]){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByGranularity);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"granularity\"]);\r\n					tempArray.add(pojo[type[key][m]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key][m]]);\r\n				}\r\n				\r\n				analysis.avg = Math.round(sumValue / list.length) + \"\";\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				plist.sort(f);\r\n				analysis.max = plist[plist.length-1]+\"\";\r\n				analysis.min = plist[0]+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[type[key][m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	var len = old[0][\"totalBitsRate\"][\"values\"].length;\r\n	for(var a in old){\r\n		if(old[a].type != \'sessions\'){\r\n			var other = {};\r\n			var analysis = {};\r\n			var values = new java.util.ArrayList();\r\n			var sumValue = 0;\r\n			for(var i=0; i<len; i++){\r\n				var sum = 0;\r\n				var tempArray = new java.util.ArrayList();\r\n				for(var b in old[a]){\r\n					if(b != \'type\'){\r\n						if(b.indexOf(\"total\") != -1){\r\n							sum += Number(old[a][b][\"values\"][i][1]);\r\n						} else {\r\n							sum -= Number(old[a][b][\"values\"][i][1]);\r\n						}\r\n						sum = sum>0?sum:0;\r\n					}\r\n				}\r\n				tempArray.add(old[0][\"totalBitsRate\"][\"values\"][i][0]);\r\n				tempArray.add(sum.toFixed(2));\r\n				values.add(tempArray);\r\n				sumValue += Number(sum);\r\n			}\r\n			analysis.avg = Math.round(sumValue / len) + \"\";\r\n				\r\n			var plist = [];\r\n			for(var i=0; i<values.length; i++){\r\n				plist.push(values[i][1]);\r\n			}\r\n			plist.sort(f);\r\n			analysis.max = plist[plist.length-1]+\"\";\r\n			analysis.min = plist[0]+\"\";\r\n			analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n			\r\n			other.values = values;\r\n			other.analysis = analysis;\r\n			old[a].other = other;\r\n		}\r\n	}\r\n	\r\n}\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}', '2022-08-03 16:50:27', '2022-08-03 16:50:29', 1, '');
INSERT INTO `galaxy_proxy` VALUES (492, 'overviewDrilldownList', '/overview/drilldown/list', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.fieldName} AS ${parameter.lad} FROM ${parameter.tableName} WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND notEmpty(${parameter.lad}) <#if parameter.name?default(\'\')?trim? length gt 0> AND ${parameter.lad} like \'%${parameter.name}%\'</#if> GROUP BY ${parameter.lad} ORDER BY SUM(common_s2c_byte_num + common_c2s_byte_num) DESC <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.tableName = \'metric_ip\';\r\n	parameter.fieldName = \'ip\';\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'country\';\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'asn\';\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.tableName = \'metric_idc_renter\';\r\n	parameter.fieldName = \'idc_renter\';\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'province\';\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'city\';\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'isp\';\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.tableName = \'metric_http_host\';\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.tableName = \'metric_ssl_sni\';\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"Object\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var val = \'\';\r\n			for (var key in pojo){    \r\n				val = pojo[key];\r\n			}\r\n			o.result[i] = val;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-03 19:20:50', '2022-08-03 19:20:52', 1, '');
INSERT INTO `galaxy_proxy` VALUES (493, 'overviewDimensionTrafficAnalysis', '/overview/dimensionTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.fieldName} AS ${parameter.lad},SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total,SUM(traffic_inbound_byte) AS inbound_bytes,SUM(traffic_outbound_byte) AS outbound_bytes,SUM(traffic_internal_byte) AS internal_bytes,SUM(traffic_through_byte) AS through_bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total,SUM(traffic_inbound_pkt) AS inbound_packets,SUM(traffic_outbound_pkt) AS outbound_packets,SUM(traffic_internal_pkt) AS internal_packets,SUM(traffic_through_pkt) AS through_packets,SUM(common_sessions) AS sessions FROM ${parameter.tableName} WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND notEmpty(${parameter.lad}) GROUP BY ${parameter.lad} <#if parameter.orderBy?default(\'\')?trim? length gt 0> ORDER BY ${parameter.orderBy} desc <#else> ORDER BY bytes_total desc </#if> <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.tableName = \'metric_ip\';\r\n	parameter.fieldName = \'ip\';\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'country\';\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'asn\';\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.tableName = \'metric_idc_renter\';\r\n	parameter.fieldName = \'idc_renter\';\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'province\';\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'city\';\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'isp\';\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.tableName = \'metric_http_host\';\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.tableName = \'metric_ssl_sni\';\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}\r\n\r\n ', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'bytesTotalRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'packetsTotalRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-03 19:56:02', '2022-08-03 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (494, 'overviewDimensionCycleTrafficAnalysis', '/overview/dimensionCycleTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.fieldName} AS ${parameter.lad},SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes,SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets,SUM(common_sessions) AS sessions FROM ${parameter.tableName} WHERE stat_time >= ${parameter.startTime} - ${parameter.timeDiff} AND stat_time < ${parameter.endTime} - ${parameter.timeDiff} AND ${parameter.lad} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY ${parameter.lad}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.tableName = \'metric_ip\';\r\n	parameter.fieldName = \'ip\';\r\n	parameter.lad = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'country\';\r\n	parameter.lad = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'asn\';\r\n	parameter.lad = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'common_app_label\';\r\n	parameter.lad = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_company\';\r\n	parameter.lad = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain\';\r\n	parameter.lad = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \'common_l7_protocol\';\r\n	parameter.lad = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.tableName = \'metric_idc_renter\';\r\n	parameter.fieldName = \'idc_renter\';\r\n	parameter.lad = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'province\';\r\n	parameter.lad = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.fieldName = \'city\';\r\n	parameter.lad = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.fieldName = \'isp\';\r\n	parameter.lad = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.fieldName = \'app_subcategory\';\r\n	parameter.lad = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.fieldName = \'domain_category_name\';\r\n	parameter.lad = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.tableName = \'metric_http_host\';\r\n	parameter.fieldName = \'http_host\';\r\n	parameter.lad = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.tableName = \'metric_ssl_sni\';\r\n	parameter.fieldName = \'ssl_sni\';\r\n	parameter.lad = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.fieldName = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.lad = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}\r\n\r\n ', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes\") != -1){\r\n					tempObj[\'bytesRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets\") != -1){\r\n					tempObj[\'packetsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\"