INSERT INTO `galaxy_proxy` VALUES (508, 'applicationPerformanceOverviewTcpLostlenPercent', '/application/performance/overview/tcpLostlenPercent', 'v1', 'GET', '/', '{\r\n    \"query\":\"<#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'>  SELECT ROUND(AVG(sequence_gap_loss_percent), 4) AS tcp_lostlen_percent_avg FROM( SELECT ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen) / SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS sequence_gap_loss_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time),INTERVAL ${parameter.step} SECOND)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime}-${parameter.timeDiff} AND common_recv_time < ${parameter.endTime}-${parameter.timeDiff} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') GROUP BY granularity ) <#else> SELECT ROUND(AVG(sequence_gap_loss_percent), 4) AS tcp_lostlen_percent_avg, ROUND(QUANTILE(sequence_gap_loss_percent, 0.5), 4) AS tcp_lostlen_percent_p50, ROUND(QUANTILE(sequence_gap_loss_percent, 0.9), 4) AS tcp_lostlen_percent_p90, ROUND(QUANTILE(sequence_gap_loss_percent, 0.95), 4) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(sequence_gap_loss_percent, 0.99), 4) AS tcp_lostlen_percent_p99 FROM( SELECT ROUND(SUM(common_c2s_tcp_lostlen + common_s2c_tcp_lostlen) / SUM(common_c2s_byte_num + common_s2c_byte_num + common_c2s_tcp_lostlen + common_s2c_tcp_lostlen), 4) AS sequence_gap_loss_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL ${parameter.step} SECOND)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') GROUP BY granularity ) </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-08-08 11:20:19', '2022-08-08 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (509, 'applicationPerformanceOverviewPacketRetransPercent', '/application/performance/overview/packetRetransPercent', 'v1', 'GET', '/', '{\r\n    \"query\":\"<#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'>  SELECT ROUND(AVG(pkt_retrans_percent), 4) AS pkt_retrans_percent_avg FROM( SELECT ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL ${parameter.step} SECOND)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime}-${parameter.timeDiff} AND common_recv_time < ${parameter.endTime}-${parameter.timeDiff} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') GROUP BY granularity ) <#else> SELECT ROUND(AVG(pkt_retrans_percent), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(pkt_retrans_percent, 0.5), 4) AS pkt_retrans_percent_p50, ROUND(QUANTILE(pkt_retrans_percent, 0.9), 4) AS pkt_retrans_percent_p90, ROUND(QUANTILE(pkt_retrans_percent, 0.95), 4) AS pkt_retrans_percent_p95, ROUND(QUANTILE(pkt_retrans_percent, 0.99), 4) AS pkt_retrans_percent_p99 FROM( SELECT ROUND(SUM(common_c2s_pkt_retrans + common_s2c_pkt_retrans)/ SUM(common_c2s_pkt_num + common_s2c_pkt_num),4) AS pkt_retrans_percent, toDateTime(toStartOfInterval(toDateTime(common_recv_time), INTERVAL ${parameter.step} SECOND)) AS granularity FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_l4_protocol IN (\'IPv4_TCP\', \'IPv6_TCP\') GROUP BY granularity ) </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-08-04 11:20:19', '2022-08-04 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (510, 'applicationPerformanceOverviewAppTrafficAnalysis', '/application/performance/overview/appTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"<#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'>  SELECT app_subcategory AS app_subcategory, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions FROM metric_application WHERE stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} AND app_subcategory IN (\'multimedia-streaming\',\'social-networking\',\'file-sharing\',\'gaming\',\'email\',\'voip-video\') GROUP BY app_subcategory <#else> SELECT app_subcategory AS app_subcategory, SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions FROM metric_application WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND app_subcategory IN (\'multimedia-streaming\',\'social-networking\',\'file-sharing\',\'gaming\',\'email\',\'voip-video\') GROUP BY app_subcategory <#if parameter.orderBy?default(\'\')?trim? length gt 0> ORDER BY ${parameter.orderBy} desc <#else> ORDER BY bytes_total desc </#if> <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if> </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function toLine(name) {   return name.replace(/([A-Z])/g,\"_$1\").toLowerCase(); }\r\nif (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\nif(parameter.orderBy){parameter.orderBy = toLine(parameter.orderBy);}', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-08 11:20:19', '2022-08-08 11:20:22', 1, '');
