INSERT INTO `galaxy_proxy` VALUES (523, 'applicationPerformanceRelatedSessions', '/application/performance/relatedSessions', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ip AS ip, SUM(client_sessions) AS client_sessions, SUM(server_sessions) AS server_sessions FROM( SELECT ip AS ip, IF(side = \'client\',SUM(common_sessions),0) AS client_sessions, IF(side = \'server\',SUM(common_sessions),0) AS server_sessions FROM metric_ip WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND ip = \'${parameter.ip}\' GROUP BY ip,side ) GROUP BY ip\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\ntempObj.sessionsRate = ((Number(tempObj.clientSessions) + Number(tempObj.serverSessions))	/ parameter.timeDiff).toFixed(2);	o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-08-09 11:20:19', '2022-08-09 11:20:22', 1, '');
