INSERT INTO `galaxy_proxy` VALUES (534, 'applicationPerformanceOverviewDrilldownDimensionClientLocationsWorldPacketRetransPercent', '/application/performance/overview/drilldown/dimension/clientLocations/world/packetRetransPercent', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT country AS country, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_ratio FROM session_record_cn WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND isNotNull(pkt_retrans_ratio) AND country IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND side = \'client\' AND ${parameter.dimension} = \'${parameter.typeVal}\' GROUP BY country ORDER BY pkt_retrans_ratio DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.dimension = \'common_server_ip\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.dimension = \'common_app_label\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.dimension = \'domain\';\r\n}', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"object\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-08-09 11:20:19', '2022-08-09 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (535, 'applicationPerformanceOverviewDrilldownDimensionClientLocationsCountryTrafficAnalysis', '/application/performance/overview/drilldown/dimension/clientLocations/country/trafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT client_country AS country, client_province AS province, SUM(common_s2c_byte_num + common_c2s_byte_num) AS bytes_total, SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS packets_total, SUM(common_sessions) AS sessions, IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_byte_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes, IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_pkt_num), 0)) AS inbound_packets, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS through_bytes, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS through_packets FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND notEmpty(client_province) AND client_country = \'${parameter.country}\' AND ${parameter.dimension} = \'${parameter.typeVal}\' GROUP BY country,province,client_zone,server_zone <#if parameter.orderBy?default(\'\')?trim? length gt 0> ORDER BY ${parameter.orderBy} desc <#else> ORDER BY bytes_total desc </#if> <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.dimension = \'common_server_ip\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.dimension = \'common_app_label\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.dimension = \'domain\';\r\n}', 'var countryCodeMap = {\"Private IP\":\"CN\",\"Afghanistan\":\"AF\",\"Albania\":\"AL\",\"Algeria\":\"DZ\",\"American Samoa\":\"AS\",\"Andorra\":\"AD\",\"Angola\":\"AO\",\"Anguilla\":\"AI\",\"Antarctica\":\"AQ\",\"Antigua and Barbuda\":\"AG\",\"Argentina\":\"AR\",\"Armenia\":\"AM\",\"Aruba\":\"AW\",\"Australia\":\"AU\",\"Austria\":\"AT\",\"Azerbaijan\":\"AZ\",\"Bahamas (the)\":\"BS\",\"Bahrain\":\"BH\",\"Bangladesh\":\"BD\",\"Barbados\":\"BB\",\"Belarus\":\"BY\",\"Belgium\":\"BE\",\"Belize\":\"BZ\",\"Benin\":\"BJ\",\"Bermuda\":\"BM\",\"Åland Islands\":\"AX\",\"Bhutan\":\"BT\",\"Bolivia (Plurinational State of)\":\"BO\",\"Bonaire, Sint Eustatius and Saba\":\"BQ\",\"Bosnia and Herzegovina\":\"BA\",\"Botswana\":\"BW\",\"Bouvet Island\":\"BV\",\"Brazil\":\"BR\",\"British Indian Ocean Territory (the)\":\"IO\",\"Brunei Darussalam\":\"BN\",\"Bulgaria\":\"BG\",\"Burkina Faso\":\"BF\",\"Burundi\":\"BI\",\"Cabo Verde\":\"CV\",\"Cambodia\":\"KH\",\"Cameroon\":\"CM\",\"Canada\":\"CA\",\"Cayman Islands (the)\":\"KY\",\"Central African Republic (the)\":\"CF\",\"Chad\":\"TD\",\"Chile\