INSERT INTO `galaxy_proxy` VALUES (550, 'applicationPerformanceOverviewDrilldownDimensionCycleTrafficAnalysis', '/application/performance/overview/drilldown/dimensionCycleTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.label} AS ${parameter.label}, SUM(bytes_total) AS bytes_total, SUM(packets_total) AS packets_total, SUM(sessions) AS sessions, SUM(inbound_bytes) AS inbound_bytes, SUM(inbound_packets) AS inbound_packets, SUM(outbound_bytes) AS outbound_bytes, SUM(outbound_packets) AS outbound_packets, SUM(internal_bytes) AS internal_bytes, SUM(internal_packets) AS internal_packets, SUM(external_bytes) AS through_bytes, SUM(external_packets) AS through_packets FROM ( SELECT ${parameter.dimension} as ${parameter.label}, SUM(common_s2c_byte_num + common_c2s_byte_num) AS bytes_total, SUM(common_s2c_pkt_num + common_c2s_pkt_num) AS packets_total, SUM(common_sessions) AS sessions, IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_byte_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes, IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_pkt_num), 0)) AS inbound_packets, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_pkt_num), 0)) AS outbound_packets, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS internal_bytes, IF(client_zone = \'internal\' AND server_zone = \'internal\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS internal_packets, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_byte_num + common_c2s_byte_num),0) AS external_bytes, IF(client_zone = \'external\' AND server_zone = \'external\' , SUM(common_s2c_pkt_num + common_c2s_pkt_num), 0) AS external_packets FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime}-${parameter.timeDiff} AND common_recv_time < ${parameter.endTime}-${parameter.timeDiff} AND ${parameter.label} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY ${parameter.label},client_zone,server_zone ) GROUP BY ${parameter.label} <#if parameter.orderBy?default(\'\')?trim? length gt 0> ORDER BY ${parameter.orderBy} desc <#else> ORDER BY bytes_total desc </#if> <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(common_client_ip,\'_\',common_server_ip)))\";\r\n	parameter.label = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_country,\'_\',server_country)))\";\r\n	parameter.label = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_asn,\'_\',server_asn)))\";\r\n	parameter.label = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.dimension = \'common_app_label\';\r\n	parameter.label = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.dimension = \'app_company\';\r\n	paramete