\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.dimension = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.label = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-04 11:20:19', '2022-08-04 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (553, 'applicationPerformanceOverviewDrilldownDimensionCycleDimensionSslConDelay', '/application/performance/overview/drilldown/dimensionSslConDelay', 'v1', 'GET', '/', '{\r\n    \"query\":\"<#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'> SELECT ${parameter.dimension} as ${parameter.label}, ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime}-${parameter.timeDiff} AND common_recv_time < ${parameter.endTime}-${parameter.timeDiff} AND common_schema_type = \'SSL\' AND ${parameter.label} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY ${parameter.label} <#else> SELECT ${parameter.dimension} as ${parameter.label}, ROUND(AVG(ssl_con_latency_ms)) AS ssl_con_latency FROM session_record_cn WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'SSL\' AND ${parameter.label} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY ${parameter.label} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', ' if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(common_client_ip,\'_\',common_server_ip)))\";\r\n	parameter.label = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_country,\'_\',server_country)))\";\r\n	parameter.label = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_asn,\'_\',server_asn)))\";\r\n	parameter.label = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.dimension = \'common_app_label\';\r\n	parameter.label = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.dimension = \'app_company\';\r\n	parameter.label = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.dimension = \'domain\';\r\n	parameter.label = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.dimension = \'common_l7_protocol\';\r\n	parameter.label = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_idc_renter,\'_\',server_idc_renter)))\";\r\n	parameter.label = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_province,\'_\',server_province)))\";\r\n	parameter.label = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_region,\'_\',server_region)))\";\r\n	parameter.label = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.dimension = \"arrayJoin(splitByChar(\'_\',concat(client_isp,\'_\',server_isp)))\";\r\n	parameter.label = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.dimension = \'app_subcategory\';\r\n	parameter.label = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.dimension = \'domain_category_name\';\r\n	parameter.label = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.dimension = \'http_host\';\r\n	parameter.label = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.dimension = \'ssl_sni\';\r\n	parameter.label = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.dimension = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.label = \'protocol_port\';\r\n}\r\n\r\nif(parameter.orderBy==\'bytesTotal\'){\r\n	parameter.orderBy=\'bytes_total\';\r\n}else if(parameter.orderBy==\'packetsTotal\'){\r\n	parameter.orderBy=\'packets_total\';\r\n}else if(parameter.orderBy==\'sessions\'){\r\n	parameter.orderBy=\'sessions\';\r\n}', ' function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-04 11:20:19', '2022-08-04 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (554, 'applicationPerformanceLocationNetworkMap', '/application/performance/location/networkMap', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT country AS country,<#if parameter.country?default(\'\')?trim? length gt 0> province AS province, <#if parameter.province?default(\'\')?trim? length gt 0> city AS city, </#if> </#if> SUM(common_c2s_byte_num + common_s2c_byte_num) AS bytes_total, SUM(traffic_inbound_byte) AS inbound_bytes, SUM(traffic_outbound_byte) AS outbound_bytes, SUM(traffic_internal_byte) AS internal_bytes, SUM(traffic_through_byte) AS through_bytes, SUM(common_c2s_pkt_num + common_s2c_pkt_num) AS packets_total, SUM(traffic_inbound_pkt) AS inbound_packets, SUM(traffic_outbound_pkt) AS outbound_packets, SUM(traffic_internal_pkt) AS internal_packets, SUM(traffic_through_pkt) AS through_packets, SUM(common_sessions) AS sessions FROM metric_region WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} <#if parameter.country?default(\'\')?trim? length gt 0><#if parameter.province?default(\'\')?trim? length gt 0> AND notEmpty(city) AND country = \'${parameter.country}\' AND province = \'${parameter.province}\' <#else> AND notEmpty(province) AND country = \'${parameter.country}\' </#if> <#else> AND notEmpty(country) </#if> AND side = \'${parameter.side}\' GROUP BY <#if parameter.country?default(\'\')?trim? length gt 0> province, <#if parameter.province?default(\'\')?trim? length gt 0> city, </#if> </#if> country <#if parameter.orderBy?default(\'\')?trim? length gt 0> ORDER BY ${parameter.orderBy} desc <#else> ORDER BY bytes_total desc </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'function toLine(name) {   return name.replace(/([A-Z])/g,\"_$1\").toLowerCase(); }\r\nif(parameter.orderBy){parameter.orderBy = toLine(parameter.orderBy);}\r\nif (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n				if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"packets_total\") != -1){\r\n					tempObj[\'totalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"total_sessions\") != -1){\r\n					tempObj[\'totalSessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_packets\") != -1){\r\n					tempObj[\'inboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_packets\") != -1){\r\n					tempObj[\'outboundPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_bytes\") != -1){\r\n					tempObj[\'internalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"internal_packets\") != -1){\r\n					tempObj[\'internalPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_bytes\") != -1){\r\n					tempObj[\'throughBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"through_packets\") != -1){\r\n					tempObj[\'throughPacketsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"sessions\") != -1){\r\n					tempObj[\'sessionsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}\r\n			}\r\n			tempObj.serverId = countryCodeMap[tempObj.country];\r\n			\r\n			if(!tempObj.serverId) {\r\n				tempObj.serverId = \"\";\r\n			}else{\r\n				// 存在地区 \r\n				if(tempObj.province){\r\n					var regionCode = countCityMap[tempObj.serverId][tempObj.province];\r\n					if(regionCode){\r\n						tempObj.serverId = regionCode;\r\n					}\r\n				}\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-10 19:56:02', '2022-08-10 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (555, 'applicationPerformanceLocationTcpSessionDelay', '/application/performance/location/tcpSessionDelay', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT country AS country, <#if parameter.country?default(\'\')?trim? length gt 0> province AS province, <#if parameter.province?default(\'\')?trim? length gt 0> city AS city, </#if> </#if> ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms FROM metric_region WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND isNotNull(avg_establish_latency_ms) <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.province?default(\'\')?trim? length gt 0> AND country IN (<#list parameter.country?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND province IN (<#list parameter.province?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND notEmpty(city) <#else>  AND country IN (<#list parameter.country?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND notEmpty(province) </#if> <#else> AND notEmpty(country) </#if> AND side = \'${parameter.side}\' GROUP BY <#if parameter.country?default(\'\')?trim? length gt 0> province, <#if parameter.province?default(\'\')?trim? length gt 0> city, </#if> </#if> country ORDER BY establish_latency_ms DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-10 19:56:02', '2022-08-18 12:44:34', 1, '');
