(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-10 19:56:02', '2022-08-18 12:45:33', 1, '');
