i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-10 19:56:02', '2022-08-18 12:46:33', 1, '');
INSERT INTO `galaxy_proxy` VALUES (558, 'applicationPerformanceLocationTcpLostlenPercent', '/application/performance/location/tcpLostlenPercent', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT country AS country, <#if parameter.country?default(\'\')?trim? length gt 0> province AS province, <#if parameter.province?default(\'\')?trim? length gt 0> city AS city, </#if> </#if> ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent FROM metric_region WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND isNotNull(tcp_lostlen_ratio) <#if parameter.country?default(\'\')?trim? length gt 0> <#if parameter.province?default(\'\')?trim? length gt 0> AND country IN (<#list parameter.country?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND province IN (<#list parameter.province?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND notEmpty(city) <#else>  AND country IN (<#list parameter.country?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) AND notEmpty(province) </#if> <#else> AND notEmpty(country) </#if> AND side = \'${parameter.side}\' GROUP BY <#if parameter.country?default(\'\')?trim? length gt 0> province, <#if parameter.province?default(\'\')?trim? length gt 0> city, </#if> </#if> country ORDER BY tcp_lostlen_percent DESC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n