INSERT INTO `galaxy_proxy` VALUES (565, 'applicationPerformanceLocationPacketsRetrains', '/application/performance/location/packetsRetrains', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT TIME_FLOOR_WITH_FILL(stat_time,\'PT${parameter.step}S\',\'zero\') AS stat_time, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent FROM metric_region WHERE stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} AND isNotNull(pkt_retrans_ratio) <#if parameter.country?default(\'\')?trim? length gt 0> AND country = \'${parameter.country}\' </#if> <#if parameter.province?default(\'\')?trim? length gt 0> AND province = \'${parameter.province}\' </#if> AND  side = \'${parameter.side}\' GROUP BY stat_time ORDER BY stat_time ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\n function sortByStatTime(a,b){  \r\n       return a.statTime - b.statTime;\r\n}\r\n\r\n\r\nif(result.success){\r\n	var o={};\r\n	 o.resultType=\"matrix\";\r\n	o.result = [];\r\n	\r\n	var list = result.data;\r\n	 if(list.length > 0){\r\n	for(var i in list){\r\n            var pojo = list[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			list[i] = tempObj;\r\n         }\r\n		var fields = new Array();\r\n		var obj = list[0];\r\n		for(var key in obj) {\r\n			if(key === \"statTime\"){\r\n				continue;\r\n			}\r\n			 fields.push(key);\r\n		}\r\n		\r\n		for(var i = 0; i < fields.length; i++) {\r\n			// 先按照时间排序\r\n			list.sort(sortByStatTime);  \r\n			var key = fields[i];\r\n			var values = new Array();\r\n			var aggregation = {};\r\n			aggregation.first = list[0][key];\r\n			aggregation.last = list[list.length - 1][key];\r\n			 \r\n			var sumValue = 0\r\n			for(var j in list){\r\n				var pojo = list[j];\r\n				var tempArray = new Array();;\r\n				 tempArray.push(pojo[\"statTime\"]);\r\n				 tempArray.push((pojo[key]).toString());\r\n				 values.push(tempArray);\r\n				sumValue += Number(pojo[key]);\r\n			 }\r\n			\r\n			list.sort(function sortByField(a,b){  \r\n				   return b[key]-a[key];\r\n			});\r\n			 \r\n			var lineObj = {};\r\n			lineObj.values = values;\r\n			lineObj.type = key;\r\n			o.result.push(lineObj);\r\n		}\r\n	}\r\n	result.code=200;\r\n	 result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n    var jsonObj = {};\r\n	for(var name in result){       \r\n		jsonObj[name] = result[name];\r\n	}\r\n	\r\n	result = JSON.stringify(jsonObj);\r\n}', '2022-08-10 19:56:02', '2022-08-10 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (566, 'overviewEventList', '/overview/event/list', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT event_${parameter.type} AS event_${parameter.type}, COUNT(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND end_time < ${parameter.endTime} GROUP BY event_${parameter.type}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-08-10 19:56:02', '2022-08-10 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (567, 'overviewEventRecentEvents', '/overview/event/recentEvents', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT event_severity AS event_severity, event_key AS event_key, event_type AS event_type FROM performance_event WHERE start_time >= ${parameter.startTime} AND end_time < ${parameter.endTime} ORDER BY start_time DESC <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-08-10 19:56:02', '2022-08-10 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (568, 'overviewEventDimensionEvents', '/overview/event/dimensionEvents', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.dimension} AS ${parameter.label}, event_severity AS event_severity, event_type AS event_type, COUNT(*) AS count FROM performance_event WHERE start_time >= ${parameter.startTime} AND end_time < ${parameter.endTime} AND ${parameter.filter} GROUP BY ${parameter.dimension},event_severity,event_type ORDER BY count DESC <#if parameter.limit?default(\'\')?trim? length gt 0> LIMIT ${parameter.limit} </#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nif(parameter.type==\'idcRenter\'){\r\n parameter.dimension = \'app_company\';\r\n parameter.label = \'app_company\';\r\n parameter.filter = \"entity_type = \'app\'\";\r\n }else if(parameter.type==\'appLabel\'){\r\n parameter.dimension = \'app_name\';\r\n parameter.label = \'app_name\';\r\n parameter.filter = \"entity_type = \'app\'\";\r\n }\r\n', 'function toHump(name) {\r\n     return name.replace(/\\_(\\w)/g, function(all, letter){\r\n         return letter.toUpperCase();\r\n     });\r\n }\r\n  if(result.success){\r\n 	var o={};\r\n 	o.resultType=\"table\";\r\n 	o.result=result.data;\r\n 	if(o.result.length > 0){\r\n 		for(var i in o.result){\r\n                         var pojo = o.result[i];\r\n 			var tempObj= {};\r\n 			for (var key in pojo){\r\n 			    var tempKey = toHump(key);\r\n 				tempObj[tempKey] = pojo[key];\r\n 			}\r\n 			o.result[i] = tempObj;\r\n         }\r\n 	}\r\n 	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n }', '2022-08-10 19:56:02', '2022-08-10 19:56:09', 1, '');
INSERT INTO `galaxy_proxy` VALUES (569, 'applicationPerformanceOverviewAppNetworkAnalysis', '/application/performance/overview/appNetworkAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT app_subcategory AS app_subcategory, ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms, ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency, ROUND(AVG(avg_ssl_con_latency_ms), 4) AS ssl_con_latency, ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent FROM metric_application WHERE <#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'> stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} <#else> stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} </#if> AND app_subcategory IN (\'multimedia-streaming\',\'social-networking\',\'file-sharing\',\'gaming\',\'email\',\'voip-video\') GROUP BY app_subcategory\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-08 11:20:19', '2022-08-08 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (570, 'applicationPerformanceOverviewDimensionNetworkAnalysis', '/application/performance/overview/dimensionNetworkAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.dimension} AS ${parameter.label}, ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms, ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency, ROUND(AVG(avg_ssl_con_latency_ms), 4) AS ssl_con_latency, ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent FROM ${parameter.tableName} WHERE <#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'> stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} <#else> stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} </#if> AND ${parameter.label} IN (<#list parameter.params?split(\",\") as level><#if !level_has_next>\'${level}\'<#else>\'${level}\',</#if></#list>) GROUP BY ${parameter.label}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.tableName = \'metric_ip\';\r\n	parameter.dimension = \'ip\';\r\n	parameter.label = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'country\';\r\n	parameter.label = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.dimension = \'asn\';\r\n	parameter.label = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'common_app_label\';\r\n	parameter.label = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'app_company\';\r\n	parameter.label = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.dimension = \'domain\';\r\n	parameter.label = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.dimension = \'common_l7_protocol\';\r\n	parameter.label = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.tableName = \'metric_idc_renter\';\r\n	parameter.dimension = \'idc_renter\';\r\n	parameter.label = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'province\';\r\n	parameter.label = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'city\';\r\n	parameter.label = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.dimension = \'isp\';\r\n	parameter.label = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'app_subcategory\';\r\n	parameter.label = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.dimension = \'domain_category_name\';\r\n	parameter.label = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.tableName = \'metric_http_host\';\r\n	parameter.dimension = \'http_host\';\r\n	parameter.label = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.tableName = \'metric_ssl_sni\';\r\n	parameter.dimension = \'ssl_sni\';\r\n	parameter.label = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.dimension = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.label = \'protocol_port\';\r\n}\r\n', ' \r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"table\";\r\n	o.result=result.data;\r\n	if(o.result.length > 0){\r\n		for(var i in o.result){\r\n            var pojo = o.result[i];\r\n			var tempObj = {};\r\n			for (var key in pojo){    \r\n				var tempKey = toHump(key);\r\n				tempObj[tempKey] = pojo[key];\r\n			}\r\n			o.result[i] = tempObj;\r\n        }\r\n	}\r\n	result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	result.message=null;\r\n}', '2022-08-08 11:20:19', '2022-08-08 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (571, 'applicationPerformanceOverviewDrilldownDimensioNetworkAnalysis', '/application/performance/overview/drilldown/dimension/networkAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\":\"SELECT ${parameter.dimension} AS ${parameter.label}, ROUND(AVG(avg_establish_latency_ms), 4) AS establish_latency_ms_avg, ROUND(QUANTILE(avg_establish_latency_ms,0.50)) AS establish_latency_ms_p50, ROUND(QUANTILE(avg_establish_latency_ms,0.90)) AS establish_latency_ms_p90, ROUND(QUANTILE(avg_establish_latency_ms,0.95)) AS establish_latency_ms_p95, ROUND(QUANTILE(avg_establish_latency_ms,0.99)) AS establish_latency_ms_p99, ROUND(AVG(avg_http_response_latency_ms), 4) AS http_response_latency_avg, ROUND(QUANTILE(avg_http_response_latency_ms,0.50)) AS http_response_latency_p50, ROUND(QUANTILE(avg_http_response_latency_ms,0.90)) AS http_response_latency_p90, ROUND(QUANTILE(avg_http_response_latency_ms,0.95)) AS http_response_latency_p95, ROUND(QUANTILE(avg_http_response_latency_ms,0.99)) AS http_response_latency_p99, ROUND(AVG(avg_ssl_con_latency_ms), 4) AS ssl_con_latency_avg, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.50)) AS ssl_con_latency_p50, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.90)) AS ssl_con_latency_p90, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.95)) AS ssl_con_latency_p95, ROUND(QUANTILE(avg_ssl_con_latency_ms,0.99)) AS ssl_con_latency_p99, ROUND(AVG(tcp_lostlen_ratio), 4) AS tcp_lostlen_percent_avg, ROUND(QUANTILE(tcp_lostlen_ratio,0.50)) AS tcp_lostlen_percent_p50, ROUND(QUANTILE(tcp_lostlen_ratio,0.90)) AS tcp_lostlen_percent_p90, ROUND(QUANTILE(tcp_lostlen_ratio,0.95)) AS tcp_lostlen_percent_p95, ROUND(QUANTILE(tcp_lostlen_ratio,0.99)) AS tcp_lostlen_percent_p99, ROUND(AVG(pkt_retrans_ratio), 4) AS pkt_retrans_percent_avg, ROUND(QUANTILE(pkt_retrans_ratio,0.50)) AS pkt_retrans_percent_p50, ROUND(QUANTILE(pkt_retrans_ratio,0.90)) AS pkt_retrans_percent_p90, ROUND(QUANTILE(pkt_retrans_ratio,0.95)) AS pkt_retrans_percent_p95, ROUND(QUANTILE(pkt_retrans_ratio,0.99)) AS pkt_retrans_percent_p99 FROM ${parameter.tableName} WHERE <#if parameter.cycle?default(\'\')?trim? length gt 0 && parameter.cycle ==\'1\'> stat_time >= ${parameter.startTime}-${parameter.timeDiff} AND stat_time < ${parameter.endTime}-${parameter.timeDiff} <#else> stat_time >= ${parameter.startTime} AND stat_time < ${parameter.endTime} </#if> <#if parameter.q?default(\'\')?trim? length gt 0> AND (${parameter.q}) </#if> GROUP BY ${parameter.label}\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nif(parameter.type==\'ip\'){\r\n	parameter.tableName = \'metric_ip\';\r\n	parameter.dimension = \'ip\';\r\n	parameter.label = \'ip\';\r\n}else if(parameter.type==\'country\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'country\';\r\n	parameter.label = \'country\';\r\n}else if(parameter.type==\'asn\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.dimension = \'asn\';\r\n	parameter.label = \'asn\';\r\n}else if(parameter.type==\'appLabel\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'common_app_label\';\r\n	parameter.label = \'app_label\';\r\n}else if(parameter.type==\'appCompany\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'app_company\';\r\n	parameter.label = \'app_company\';\r\n}else if(parameter.type==\'domain\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.dimension = \'domain\';\r\n	parameter.label = \'domain\';\r\n}else if(parameter.type==\'l7Protocol\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.dimension = \'common_l7_protocol\';\r\n	parameter.label = \'l7_protocol\';\r\n}else if(parameter.type==\'idcRenter\'){\r\n	parameter.tableName = \'metric_idc_renter\';\r\n	parameter.dimension = \'idc_renter\';\r\n	parameter.label = \'idc_renter\';\r\n}else if(parameter.type==\'province\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'province\';\r\n	parameter.label = \'province\';\r\n}else if(parameter.type==\'city\'){\r\n	parameter.tableName = \'metric_region\';\r\n	parameter.dimension = \'city\';\r\n	parameter.label = \'city\';\r\n}else if(parameter.type==\'isp\'){\r\n	parameter.tableName = \'metric_asn\';\r\n	parameter.dimension = \'isp\';\r\n	parameter.label = \'isp\';\r\n}else if(parameter.type==\'appSubcategory\'){\r\n	parameter.tableName = \'metric_application\';\r\n	parameter.dimension = \'app_subcategory\';\r\n	parameter.label = \'app_subcategory\';\r\n}else if(parameter.type==\'domainCategoryName\'){\r\n	parameter.tableName = \'metric_domain\';\r\n	parameter.dimension = \'domain_category_name\';\r\n	parameter.label = \'domain_category_name\';\r\n}else if(parameter.type==\'httpHost\'){\r\n	parameter.tableName = \'metric_http_host\';\r\n	parameter.dimension = \'http_host\';\r\n	parameter.label = \'http_host\';\r\n}else if(parameter.type==\'sslSni\'){\r\n	parameter.tableName = \'metric_ssl_sni\';\r\n	parameter.dimension = \'ssl_sni\';\r\n	parameter.label = \'ssl_sni\';\r\n}else if(parameter.type==\'protocolPort\'){\r\n	parameter.tableName = \'metric_protocol\';\r\n	parameter.dimension = \"concat(common_l7_protocol,\':\',toString(common_server_port))\";\r\n	parameter.label = \'protocol_port\';\r\n}\r\n', 'function toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nif(result.success){\r\n	var o={};\r\n	o.resultType=\"object\"\r\n	 o.result={};\r\n if(result.data.length > 0){\r\n	var pojo = result.data[0];\r\n 		var tempObj= {};\r\n 	for (var key in pojo){\r\n		var tempKey = toHump(key);\r\n		tempObj[tempKey] = pojo[key];\r\n		}\r\n		o.result = tempObj;\r\n 			}\r\n	 result.code=200;\r\n	result.data=o;\r\n	result.msg = result.message;\r\n	 result.message=null;\r\n}', '2022-08-08 11:20:19', '2022-08-08 11:20:22', 1, '');
INSERT INTO `galaxy_proxy` VALUES (572, 'dnsOverviewTotalTrafficAnalysis', '/dns/overview/totalTrafficAnalysis', 'v1', 'GET', '/', '{\r\n    \"query\": \"SELECT granularity AS granularity, SUM(total_bytes) AS bytes_total, SUM(inbound_bytes) AS inbound_bytes, SUM(outbound_bytes) AS outbound_bytes, ROUND(SUM(query_rate) ,4) as query_rate FROM ( SELECT TIME_FLOOR_WITH_FILL(common_recv_time,\'PT${parameter.step}S\',\'zero\') AS granularity, SUM(common_s2c_byte_num + common_c2s_byte_num) AS total_bytes, IF(client_zone = \'internal\' AND server_zone = \'external\' , SUM(common_s2c_byte_num), IF(client_zone = \'external\' AND server_zone = \'internal\', SUM(common_c2s_byte_num), 0)) AS inbound_bytes, IF(client_zone = \'external\' AND server_zone = \'internal\' , SUM(common_s2c_byte_num), IF(client_zone = \'internal\' AND server_zone = \'external\', SUM(common_c2s_byte_num), 0)) AS outbound_bytes, ROUND(COUNT(*)/${parameter.step},4) AS query_rate FROM session_record_cn AS a WHERE common_recv_time >= ${parameter.startTime} AND common_recv_time < ${parameter.endTime} AND common_schema_type = \'DNS\' GROUP BY granularity,client_zone,server_zone ORDER BY granularity ) GROUP BY granularity ORDER BY granularity ASC\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}', '{}', 'if (!parameter.endTime) {\r\n    parameter.endTime = parseInt(+new Date()/1000);\r\n}\r\nif (!parameter.startTime) {\r\n    parameter.startTime = parameter.endTime - 60 * 60;\r\n}\r\n/*计算step,series最多显示100个点，单位：s*/\r\nparameter.step = (parameter.endTime-parameter.startTime)/100;\r\n\r\nparameter.timeDiff = parameter.endTime - parameter.startTime;\r\n\r\nparameter.endTime = \'toDateTime(\'+parameter.endTime+\')\';\r\nparameter.startTime = \'toDateTime(\'+parameter.startTime+\')\';', 'function f(a,b) {\r\n	return (a - b);\r\n}\r\n\r\nfunction getPercentile(list, p){\r\n	var n = list.length;\r\n	list.sort(f);\r\n	var px =  p*(n-1);\r\n	var i = Math.floor(px);\r\n	var g = px - i;\r\n	if(g==0){\r\n		return list[i];\r\n	}else{\r\n		return (1-g)*list[i]+g*list[i+1];\r\n	}\r\n}\r\n\r\nfunction toHump(name) {\r\n    return name.replace(/\\_(\\w)/g, function(all, letter){\r\n        return letter.toUpperCase();\r\n    });\r\n}\r\n\r\nfunction sortByStatTime(a,b){  \r\n       return a.granularity - b.granularity;\r\n}\r\n\r\nif(result.success){\r\n	var o = {};\r\n	o.resultType=\"object\";\r\n	var old = new java.util.ArrayList();\r\n	var list = result.data;\r\n	if(list.length > 0){\r\n		for(var i in list){\r\n			var pojo = list[i];\r\n			var tempObj= {};\r\n			for (var key in pojo){\r\nif(key.indexOf(\"granularity\") != -1){\r\n					tempObj[\'granularity\'] = pojo[key]\r\n				}else if(key.indexOf(\"bytes_total\") != -1){\r\n					tempObj[\'totalBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"inbound_bytes\") != -1){\r\n					tempObj[\'inboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"outbound_bytes\") != -1){\r\n					tempObj[\'outboundBitsRate\'] = (pojo[key] / parameter.timeDiff).toFixed(2)\r\n				}else if(key.indexOf(\"query_rate\") != -1){\r\n					tempObj[\'totalQueryRate\'] = pojo[key]\r\n				}\r\n			}\r\n			list[i] = tempObj;\r\n			list[i].statTime = list[i].statTime;\r\n		}\r\n		var bytes = [];\r\n		var queries = [];\r\n	for(var key in list[0]){\r\n			if(key.indexOf(\"Bits\") != -1){\r\n				bytes.push(key);\r\n			} else if(key.indexOf(\"Query\") != -1){\r\n				queries.push(key);\r\n			}\r\n		}\r\n		var type = {};\r\n		type.bytes = bytes;\r\n		type.queries = queries;\r\n	for(var key in type){\r\n			var obj = {};\r\n			obj.type = key;\r\n			for(var m in type[key]){\r\n				var zong = {};\r\n				var analysis = {};\r\n				var values = new java.util.ArrayList();\r\n				list.sort(sortByStatTime);\r\n				var sumValue = 0;\r\n				for(var j in list){\r\n					var pojo = list[j];\r\n					var tempArray = new java.util.ArrayList();\r\n					tempArray.add(pojo[\"granularity\"]);\r\n					tempArray.add(pojo[type[key][m]] + \"\");\r\n					values.add(tempArray);\r\n					sumValue += Number(pojo[type[key][m]]);\r\n				}\r\n				\r\n				analysis.avg = Math.round((sumValue / list.length)*100)/100 + \"\";\r\n				\r\n				var plist = [];\r\n				for(var i=0; i<values.length; i++){\r\n					plist.push(values[i][1]);\r\n				}\r\n				plist.sort(f);\r\n				analysis.max = plist[plist.length-1]+\"\";\r\n				analysis.min = plist[0]+\"\";\r\n				analysis.p95 = getPercentile(plist, 0.95)+\"\";\r\n				\r\n				\r\n				zong.values = values;\r\n				zong.analysis = analysis;\r\n				\r\n				obj[type[key][m]] = zong;\r\n			}\r\n			old.add(obj);\r\n		}\r\n	}\r\n	\r\n	o.result = old;\r\n	result.code=200;\r\n 	result.data=o;\r\n 	result.msg = result.message;\r\n 	result.message=null;\r\n}', '2022-09-16 10:03:32', '2022-09-16 13:03:36', 1, '');
